import{_ as e,o as s,c as i,a3 as t}from"./chunks/framework.BlfGB29P.js";const k=JSON.parse('{"title":"HTTP 缓存","description":"","frontmatter":{"title":"HTTP 缓存","outline":[2,3],"article":{"type":"concept","structure":"tutorial-with-api"}},"headers":[],"relativePath":"frontend/guide/core/web/network/caching.md","filePath":"frontend/guide/core/web/network/caching.md","lastUpdated":1785217527000}'),n={name:"frontend/guide/core/web/network/caching.md"};function l(h,a,d,p,r,o){return s(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="http-缓存" tabindex="-1">HTTP 缓存 <a class="header-anchor" href="#http-缓存" aria-label="Permalink to &quot;HTTP 缓存&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>HTTP 缓存保存的是“某个请求对应的响应”，后续请求只有命中同一缓存键并满足复用条件，才能直接使用或向服务器验证。它不是简单的“把 GET 结果存一段时间”：缓存还要判断响应能否存储、是否新鲜、是否必须重新验证、如何区分内容协商结果，以及共享缓存能否接触用户数据。</p><p>本篇以 RFC 9111 的模型解释缓存字段与浏览器行为。Service Worker 的 Cache API、应用状态缓存和离线同步属于其他缓存层，不与 HTTP cache 混为一谈。</p><h2 id="_1-缓存模型" tabindex="-1">1. 缓存模型 <a class="header-anchor" href="#_1-缓存模型" aria-label="Permalink to &quot;1. 缓存模型&quot;">​</a></h2><h3 id="_1-1-private-cache" tabindex="-1">1.1 Private Cache <a class="header-anchor" href="#_1-1-private-cache" aria-label="Permalink to &quot;1.1 Private Cache&quot;">​</a></h3><p>私有缓存只服务单个用户代理，典型实现是浏览器 HTTP cache。它可以保存带用户上下文的响应，但仍必须服从 <code>Cache-Control</code>、<code>Vary</code> 和验证器等规则。</p><p>“私有”描述共享范围，不等于响应内容已加密，也不意味着浏览器一定把它永久写入磁盘。</p><h3 id="_1-2-shared-cache" tabindex="-1">1.2 Shared Cache <a class="header-anchor" href="#_1-2-shared-cache" aria-label="Permalink to &quot;1.2 Shared Cache&quot;">​</a></h3><p>共享缓存服务多个用户，例如 CDN、反向代理或网关缓存。它能减少回源流量，却必须避免把一个用户的响应返回给另一个用户。</p><p>共享缓存会关注 <code>s-maxage</code>、<code>private</code>、<code>Authorization</code> 等规则。是否实际缓存还受产品配置、容量、淘汰策略和缓存键影响。</p><h3 id="_1-3-缓存键" tabindex="-1">1.3 缓存键 <a class="header-anchor" href="#_1-3-缓存键" aria-label="Permalink to &quot;1.3 缓存键&quot;">​</a></h3><p>缓存首先按请求方法和目标 URI 匹配，再结合 <code>Vary</code> 指定的请求字段选择响应。实际 CDN 可能把协议、主机、查询参数、Cookie 或自定义字段纳入产品级缓存键。</p><p>以下 URL 默认是不同目标：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/products?page=1</span></span>\n<span class="line"><span>/products?page=2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>如果响应根据 <code>Accept-Language</code> 变化，还应返回：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Vary</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Accept-Language</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>否则缓存可能把中文表示复用于需要英文表示的请求。</p><h3 id="_1-4-命中后的两条路径" tabindex="-1">1.4 命中后的两条路径 <a class="header-anchor" href="#_1-4-命中后的两条路径" aria-label="Permalink to &quot;1.4 命中后的两条路径&quot;">​</a></h3><p>缓存命中不等于一定零请求：</p><ol><li>响应仍然新鲜：直接复用已存储响应。</li><li>响应已过期或要求验证：发出条件请求，服务器可返回 <code>304 Not Modified</code>。</li></ol><p>未命中、禁止存储或验证失败时，才需要获取新的完整响应。</p><h2 id="_2-响应何时可以存储" tabindex="-1">2. 响应何时可以存储 <a class="header-anchor" href="#_2-响应何时可以存储" aria-label="Permalink to &quot;2. 响应何时可以存储&quot;">​</a></h2><h3 id="_2-1-常见前提" tabindex="-1">2.1 常见前提 <a class="header-anchor" href="#_2-1-常见前提" aria-label="Permalink to &quot;2.1 常见前提&quot;">​</a></h3><p>缓存通常需要同时满足：</p><ul><li>请求方法可缓存，实践中主要是 GET 和 HEAD；</li><li>状态码允许缓存，或响应提供明确的新鲜度信息；</li><li>响应没有 <code>no-store</code>；</li><li>共享缓存没有受到 <code>private</code> 或认证规则限制；</li><li>缓存实现愿意保存该响应。</li></ul><p>RFC 允许某些状态码在没有显式新鲜度时进行启发式缓存，但业务接口不应依赖各实现自行猜测。</p><h3 id="_2-2-默认可缓存状态" tabindex="-1">2.2 默认可缓存状态 <a class="header-anchor" href="#_2-2-默认可缓存状态" aria-label="Permalink to &quot;2.2 默认可缓存状态&quot;">​</a></h3><p><code>200</code>、<code>203</code>、<code>204</code>、<code>206</code>、<code>300</code>、<code>301</code>、<code>308</code>、<code>404</code>、<code>405</code>、<code>410</code>、<code>414</code>、<code>501</code> 等状态在满足其他条件时可以被启发式缓存。<code>302</code>、<code>307</code> 等通常需要显式新鲜度信息。</p><p>“错误响应”不等于不能缓存。短时间缓存 <code>404</code> 可以保护源站，但发布新资源时也可能延迟可见性。</p><h3 id="_2-3-请求方法边界" tabindex="-1">2.3 请求方法边界 <a class="header-anchor" href="#_2-3-请求方法边界" aria-label="Permalink to &quot;2.3 请求方法边界&quot;">​</a></h3><p>规范允许扩展方法声明缓存语义，但常见浏览器和中间缓存主要支持 GET / HEAD。POST 响应即使携带显式新鲜度，跨实现复用能力也有限，不能把它作为通用前端缓存方案。</p><h3 id="_2-4-set-cookie-不是禁止缓存指令" tabindex="-1">2.4 <code>Set-Cookie</code> 不是禁止缓存指令 <a class="header-anchor" href="#_2-4-set-cookie-不是禁止缓存指令" aria-label="Permalink to &quot;2.4 `Set-Cookie` 不是禁止缓存指令&quot;">​</a></h3><p>响应包含 <code>Set-Cookie</code> 并不会自动使它不可缓存。个性化响应必须明确发送：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> private, no-store</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>共享缓存还应配置不缓存带认证或会话上下文的响应，不能把安全性押在某个 CDN 的默认行为上。</p><h2 id="_3-新鲜度与响应年龄" tabindex="-1">3. 新鲜度与响应年龄 <a class="header-anchor" href="#_3-新鲜度与响应年龄" aria-label="Permalink to &quot;3. 新鲜度与响应年龄&quot;">​</a></h2><h3 id="_3-1-max-age" tabindex="-1">3.1 <code>max-age</code> <a class="header-anchor" href="#_3-1-max-age" aria-label="Permalink to &quot;3.1 `max-age`&quot;">​</a></h3><p><code>max-age=N</code> 表示响应从生成时间起可保持新鲜 N 秒：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public, max-age=300</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Date</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tue, 28 Jul 2026 02:00:00 GMT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这不是“收到后再保存 300 秒”的绝对保证。缓存会综合 <code>Date</code>、传输延迟和 <code>Age</code> 估算当前年龄。</p><h3 id="_3-2-s-maxage" tabindex="-1">3.2 <code>s-maxage</code> <a class="header-anchor" href="#_3-2-s-maxage" aria-label="Permalink to &quot;3.2 `s-maxage`&quot;">​</a></h3><p><code>s-maxage</code> 只约束共享缓存，并在共享缓存中覆盖 <code>max-age</code> 或 <code>Expires</code>：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public, max-age=60, s-maxage=600</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>浏览器可新鲜复用 60 秒，CDN 可新鲜复用 600 秒。它适合“边缘统一缓存更久、终端较快验证”的响应。</p><h3 id="_3-3-expires" tabindex="-1">3.3 <code>Expires</code> <a class="header-anchor" href="#_3-3-expires" aria-label="Permalink to &quot;3.3 `Expires`&quot;">​</a></h3><p><code>Expires</code> 用绝对 HTTP 日期表达过期时间：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Date</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tue, 28 Jul 2026 02:00:00 GMT</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Expires</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tue, 28 Jul 2026 02:05:00 GMT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>Cache-Control: max-age</code> 存在时优先使用它。现代服务通常以 <code>max-age</code> 为主，<code>Expires</code> 用于兼容旧实现。</p><h3 id="_3-4-age" tabindex="-1">3.4 <code>Age</code> <a class="header-anchor" href="#_3-4-age" aria-label="Permalink to &quot;3.4 `Age`&quot;">​</a></h3><p>共享缓存转发响应时可添加或更新 <code>Age</code>，表示响应被源站生成后经过的估算秒数：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Age</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 125</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public, max-age=300</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这份响应只剩大约 175 秒的新鲜期。<code>Age</code> 不是资源在业务上的创建年龄。</p><h3 id="_3-5-启发式新鲜度" tabindex="-1">3.5 启发式新鲜度 <a class="header-anchor" href="#_3-5-启发式新鲜度" aria-label="Permalink to &quot;3.5 启发式新鲜度&quot;">​</a></h3><p>没有显式新鲜度时，缓存可能依据 <code>Last-Modified</code> 等信息估算可复用时间。不同实现的策略不完全相同，因此 HTML、API 和关键静态资源都应给出明确缓存策略。</p><h2 id="_4-响应端-cache-control" tabindex="-1">4. 响应端 <code>Cache-Control</code> <a class="header-anchor" href="#_4-响应端-cache-control" aria-label="Permalink to &quot;4. 响应端 `Cache-Control`&quot;">​</a></h2><h3 id="_4-1-public-与-private" tabindex="-1">4.1 <code>public</code> 与 <code>private</code> <a class="header-anchor" href="#_4-1-public-与-private" aria-label="Permalink to &quot;4.1 `public` 与 `private`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指令</th><th>含义</th><th>常见用途</th></tr></thead><tbody><tr><td><code>public</code></td><td>允许共享缓存保存，即使响应通常受认证限制</td><td>所有用户相同的公开资源</td></tr><tr><td><code>private</code></td><td>只能由私有缓存保存</td><td>用户个性化但允许浏览器缓存的内容</td></tr></tbody></table><p><code>private</code> 不等于 <code>no-store</code>。浏览器仍可能存储并复用它。</p><h3 id="_4-2-no-cache" tabindex="-1">4.2 <code>no-cache</code> <a class="header-anchor" href="#_4-2-no-cache" aria-label="Permalink to &quot;4.2 `no-cache`&quot;">​</a></h3><p><code>no-cache</code> 允许存储，但每次复用前必须向源站验证：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> no-cache</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ETag</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;home-v42&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>名称容易误导。它适合需要及时更新、但希望通过 <code>304</code> 节省响应体传输的 HTML。</p><h3 id="_4-3-no-store" tabindex="-1">4.3 <code>no-store</code> <a class="header-anchor" href="#_4-3-no-store" aria-label="Permalink to &quot;4.3 `no-store`&quot;">​</a></h3><p><code>no-store</code> 要求缓存不要存储当前请求或响应：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> private, no-store</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>适合一次性下载地址、敏感账户信息等。它不会追溯删除此前已保存的旧响应，也不能替代客户端内存清理和服务端权限控制。</p><h3 id="_4-4-must-revalidate-与-proxy-revalidate" tabindex="-1">4.4 <code>must-revalidate</code> 与 <code>proxy-revalidate</code> <a class="header-anchor" href="#_4-4-must-revalidate-与-proxy-revalidate" aria-label="Permalink to &quot;4.4 `must-revalidate` 与 `proxy-revalidate`&quot;">​</a></h3><p>响应过期后，<code>must-revalidate</code> 要求缓存必须成功验证才能复用，不能在断网时擅自返回旧内容。<code>proxy-revalidate</code> 只约束共享缓存。</p><p>需要强一致且过期数据不可接受时使用；离线体验优先的内容则要谨慎。</p><h3 id="_4-5-immutable" tabindex="-1">4.5 <code>immutable</code> <a class="header-anchor" href="#_4-5-immutable" aria-label="Permalink to &quot;4.5 `immutable`&quot;">​</a></h3><p><code>immutable</code> 表示响应在新鲜期内不会改变，客户端无需因普通刷新而验证：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public, max-age=31536000, immutable</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>它应与内容哈希 URL 配合。对固定 URL 却会原地覆盖的文件使用一年 <code>immutable</code>，会让旧版本难以及时失效。</p><h3 id="_4-6-stale-while-revalidate" tabindex="-1">4.6 <code>stale-while-revalidate</code> <a class="header-anchor" href="#_4-6-stale-while-revalidate" aria-label="Permalink to &quot;4.6 `stale-while-revalidate`&quot;">​</a></h3><p>允许缓存先返回有限时间内的过期响应，同时在后台重新验证：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public, max-age=60, stale-while-revalidate=300</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>它降低等待时间，但客户端可能看到旧数据。是否由浏览器或 CDN 完整支持、后台验证何时完成，要结合目标环境验证。</p><h3 id="_4-7-stale-if-error" tabindex="-1">4.7 <code>stale-if-error</code> <a class="header-anchor" href="#_4-7-stale-if-error" aria-label="Permalink to &quot;4.7 `stale-if-error`&quot;">​</a></h3><p>当回源失败时，缓存可在指定秒数内返回过期响应：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public, max-age=60, stale-if-error=86400</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>它提高可用性，却不适合价格、库存、权限等“旧数据比报错更危险”的结果。</p><h2 id="_5-请求端缓存指令" tabindex="-1">5. 请求端缓存指令 <a class="header-anchor" href="#_5-请求端缓存指令" aria-label="Permalink to &quot;5. 请求端缓存指令&quot;">​</a></h2><p>客户端也可以表达本次请求的复用要求：</p><table tabindex="0"><thead><tr><th>指令</th><th>请求意图</th></tr></thead><tbody><tr><td><code>no-cache</code></td><td>使用前必须验证已有响应</td></tr><tr><td><code>no-store</code></td><td>不使用也不存储本次交换</td></tr><tr><td><code>max-age=N</code></td><td>只接受年龄不超过 N 秒的响应</td></tr><tr><td><code>min-fresh=N</code></td><td>要求响应未来至少 N 秒仍新鲜</td></tr><tr><td><code>max-stale[=N]</code></td><td>愿意接受有限过期响应</td></tr><tr><td><code>only-if-cached</code></td><td>只使用缓存，不能访问网络</td></tr></tbody></table><p>请求指令不是命令服务器修改原响应策略，也不保证所有中间层按业务期望实现。</p><p>浏览器 Fetch 的 <code>cache</code> 选项会生成或影响相应的缓存行为，详见第 11 节。</p><h2 id="_6-验证器与条件请求" tabindex="-1">6. 验证器与条件请求 <a class="header-anchor" href="#_6-验证器与条件请求" aria-label="Permalink to &quot;6. 验证器与条件请求&quot;">​</a></h2><h3 id="_6-1-etag" tabindex="-1">6.1 <code>ETag</code> <a class="header-anchor" href="#_6-1-etag" aria-label="Permalink to &quot;6.1 `ETag`&quot;">​</a></h3><p><code>ETag</code> 是服务器为当前表示生成的实体标签：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ETag</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;product-42-v7&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>缓存验证时发送：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">If-None-Match</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;product-42-v7&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>若表示未变化，服务器返回 <code>304</code>；发生变化则返回新的完整响应和新 ETag。</p><h3 id="_6-2-强验证与弱验证" tabindex="-1">6.2 强验证与弱验证 <a class="header-anchor" href="#_6-2-强验证与弱验证" aria-label="Permalink to &quot;6.2 强验证与弱验证&quot;">​</a></h3><p>强 ETag 表示字节级等价，适用于范围请求等需要精确匹配的场景。弱 ETag 以 <code>W/</code> 开头：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ETag</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> W/&quot;product-42-v7&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>它表示语义等价但字节可能不同，例如 JSON 空白或压缩方式变化。弱标签不能用于要求强比较的 <code>If-Range</code>。</p><h3 id="_6-3-last-modified" tabindex="-1">6.3 <code>Last-Modified</code> <a class="header-anchor" href="#_6-3-last-modified" aria-label="Permalink to &quot;6.3 `Last-Modified`&quot;">​</a></h3><p>服务器也可以返回最后修改时间：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Last-Modified</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tue, 28 Jul 2026 01:40:00 GMT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>客户端随后发送 <code>If-Modified-Since</code>。HTTP 日期只有秒级精度，服务器时间和生成逻辑也可能不可靠；可生成稳定版本标识时优先使用 ETag。</p><h3 id="_6-4-验证器优先级" tabindex="-1">6.4 验证器优先级 <a class="header-anchor" href="#_6-4-验证器优先级" aria-label="Permalink to &quot;6.4 验证器优先级&quot;">​</a></h3><p>同时存在 <code>If-None-Match</code> 和 <code>If-Modified-Since</code> 时，服务器优先评价 <code>If-None-Match</code>。同时发送 ETag 与 Last-Modified 可兼顾不同缓存实现，但两者必须描述同一版本。</p><h2 id="_7-304-not-modified" tabindex="-1">7. <code>304 Not Modified</code> <a class="header-anchor" href="#_7-304-not-modified" aria-label="Permalink to &quot;7. `304 Not Modified`&quot;">​</a></h2><h3 id="_7-1-交互过程" tabindex="-1">7.1 交互过程 <a class="header-anchor" href="#_7-1-交互过程" aria-label="Permalink to &quot;7.1 交互过程&quot;">​</a></h3><p>首次请求：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OK</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> no-cache</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ETag</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;app-shell-v8&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> text/html</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;!doctype html&gt;...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>再次请求：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> / </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">If-None-Match</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;app-shell-v8&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>未修改时：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 304</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Not Modified</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ETag</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;app-shell-v8&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> no-cache</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Date</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tue, 28 Jul 2026 02:10:00 GMT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>304</code> 不携带表示内容。缓存更新适用的元数据，再把已保存响应体与更新后的字段组合成客户端可用响应。</p><h3 id="_7-2-304-不是普通空响应" tabindex="-1">7.2 <code>304</code> 不是普通空响应 <a class="header-anchor" href="#_7-2-304-不是普通空响应" aria-label="Permalink to &quot;7.2 `304` 不是普通空响应&quot;">​</a></h3><p>没有对应缓存实体时，客户端无法单独使用 <code>304</code>。服务端业务代码也不应把它当作“请求成功但数组为空”。</p><h3 id="_7-3-验证不等于一定更快" tabindex="-1">7.3 验证不等于一定更快 <a class="header-anchor" href="#_7-3-验证不等于一定更快" aria-label="Permalink to &quot;7.3 验证不等于一定更快&quot;">​</a></h3><p>条件请求节省下载字节，但仍消耗网络往返、连接和服务端验证时间。内容哈希静态资源更适合直接长期新鲜复用。</p><h2 id="_8-vary-与内容协商" tabindex="-1">8. <code>Vary</code> 与内容协商 <a class="header-anchor" href="#_8-vary-与内容协商" aria-label="Permalink to &quot;8. `Vary` 与内容协商&quot;">​</a></h2><h3 id="_8-1-建立变体" tabindex="-1">8.1 建立变体 <a class="header-anchor" href="#_8-1-建立变体" aria-label="Permalink to &quot;8.1 建立变体&quot;">​</a></h3><p>响应随某个请求字段变化时，用 <code>Vary</code> 声明：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Vary</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Accept-Encoding, Accept-Language</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>缓存只有在这些字段与已存请求匹配时才能复用响应。</p><h3 id="_8-2-控制基数" tabindex="-1">8.2 控制基数 <a class="header-anchor" href="#_8-2-控制基数" aria-label="Permalink to &quot;8.2 控制基数&quot;">​</a></h3><p><code>Vary: User-Agent</code> 可能产生大量变体，显著降低命中率。能用响应式布局、客户端特性检测或少量规范化设备类别解决时，不应直接按完整 User-Agent 分裂缓存。</p><h3 id="_8-3-vary" tabindex="-1">8.3 <code>Vary: *</code> <a class="header-anchor" href="#_8-3-vary" aria-label="Permalink to &quot;8.3 `Vary: *`&quot;">​</a></h3><p><code>Vary: *</code> 表示任何未明确的请求因素都可能影响响应，缓存无法通过后续请求字段确认匹配，因此不能正常复用该响应。</p><h3 id="_8-4-cors-边界" tabindex="-1">8.4 CORS 边界 <a class="header-anchor" href="#_8-4-cors-边界" aria-label="Permalink to &quot;8.4 CORS 边界&quot;">​</a></h3><p>若响应按请求 <code>Origin</code> 返回不同的 <code>Access-Control-Allow-Origin</code>，通常需要：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Vary</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Origin</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这只防止缓存混用不同 Origin 的响应，不代表 CORS 配置本身正确。CORS 的权限模型属于 Web 安全主题。</p><h2 id="_9-常见资源的缓存策略" tabindex="-1">9. 常见资源的缓存策略 <a class="header-anchor" href="#_9-常见资源的缓存策略" aria-label="Permalink to &quot;9. 常见资源的缓存策略&quot;">​</a></h2><h3 id="_9-1-内容哈希静态资源" tabindex="-1">9.1 内容哈希静态资源 <a class="header-anchor" href="#_9-1-内容哈希静态资源" aria-label="Permalink to &quot;9.1 内容哈希静态资源&quot;">​</a></h3><p>文件名随内容变化：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/assets/app.8f4c21.js</span></span>\n<span class="line"><span>/assets/logo.2a69de.svg</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>响应：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public, max-age=31536000, immutable</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>发布新内容会生成新 URL，旧文件可继续安全缓存。部署时必须让 HTML 先后兼容新旧资源，不能立即删除仍被旧 HTML 引用的文件。</p><h3 id="_9-2-html-入口" tabindex="-1">9.2 HTML 入口 <a class="header-anchor" href="#_9-2-html-入口" aria-label="Permalink to &quot;9.2 HTML 入口&quot;">​</a></h3><p>HTML 引用当前版本资源，通常要求尽快验证：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> no-cache</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ETag</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;index-v108&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这样既能拿到 <code>304</code>，又不会把旧入口无条件缓存很久。</p><h3 id="_9-3-公开-api" tabindex="-1">9.3 公开 API <a class="header-anchor" href="#_9-3-公开-api" aria-label="Permalink to &quot;9.3 公开 API&quot;">​</a></h3><p>所有用户得到相同结果、允许短暂旧数据：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public, max-age=30, s-maxage=300, stale-while-revalidate=60</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ETag</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;catalog-v52&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Vary</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Accept-Encoding</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>共享缓存复用 5 分钟，浏览器 30 秒后需处理过期，具体重验证由所在缓存层完成。</p><h3 id="_9-4-个性化-api" tabindex="-1">9.4 个性化 API <a class="header-anchor" href="#_9-4-个性化-api" aria-label="Permalink to &quot;9.4 个性化 API&quot;">​</a></h3><p>账户余额、权限或订单：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> private, no-store</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>若业务允许浏览器保存并验证个性化内容，可改为 <code>private, no-cache</code> 并提供 ETag，但需要结合退出登录清理、设备共享风险和数据敏感度评审。</p><h2 id="_10-一套完整配置" tabindex="-1">10. 一套完整配置 <a class="header-anchor" href="#_10-一套完整配置" aria-label="Permalink to &quot;10. 一套完整配置&quot;">​</a></h2><p>假设应用包含入口 HTML、哈希资源、公共分类和当前用户资料：</p><table tabindex="0"><thead><tr><th>路径</th><th>响应头</th><th>选择原因</th></tr></thead><tbody><tr><td><code>/index.html</code></td><td><code>Cache-Control: no-cache</code> + ETag</td><td>每次确认入口版本，未变化只传 304</td></tr><tr><td><code>/assets/app.8f4c21.js</code></td><td><code>public, max-age=31536000, immutable</code></td><td>URL 随内容变化，可长期复用</td></tr><tr><td><code>/api/categories</code></td><td><code>public, max-age=60, s-maxage=600</code> + ETag</td><td>公共数据，CDN 比浏览器缓存更久</td></tr><tr><td><code>/api/me</code></td><td><code>private, no-store</code></td><td>用户敏感数据，不进入共享或持久缓存</td></tr></tbody></table><p>一次版本发布后的结果流：</p><ol><li>用户再次访问 <code>/index.html</code>，浏览器带旧 ETag 验证。</li><li>服务器返回新 HTML 和新 ETag。</li><li>HTML 引用新的哈希 JS URL，浏览器获取一次后长期缓存。</li><li>旧 JS URL 保持可访问，避免仍持有旧 HTML 的客户端加载失败。</li><li>公共分类由 CDN 复用；用户资料始终回源并重新鉴权。</li></ol><p>这套配置把“是否需要及时知道新版本”和“文件内容是否可能在同一 URL 下变化”分开处理。</p><h2 id="_11-fetch-的-request-cache" tabindex="-1">11. Fetch 的 <code>Request.cache</code> <a class="header-anchor" href="#_11-fetch-的-request-cache" aria-label="Permalink to &quot;11. Fetch 的 `Request.cache`&quot;">​</a></h2><h3 id="_11-1-模式速查" tabindex="-1">11.1 模式速查 <a class="header-anchor" href="#_11-1-模式速查" aria-label="Permalink to &quot;11.1 模式速查&quot;">​</a></h3><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> loadCategories</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> response</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/api/categories&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { cache: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;default&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">response.ok) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">throw</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`Request failed: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">response</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> response.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">json</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Promise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">unknown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> loadCategories</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">then</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">categories</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(categories))</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><table tabindex="0"><thead><tr><th>值</th><th>浏览器缓存行为概览</th></tr></thead><tbody><tr><td><code>default</code></td><td>按 HTTP 缓存规则查找、验证或回源</td></tr><tr><td><code>no-store</code></td><td>不从 HTTP cache 读取，也不把响应写入其中</td></tr><tr><td><code>reload</code></td><td>跳过读取，获取后可更新缓存</td></tr><tr><td><code>no-cache</code></td><td>即使有新鲜响应也先验证，再更新缓存</td></tr><tr><td><code>force-cache</code></td><td>优先使用匹配响应，包括允许的过期响应；没有则回源</td></tr><tr><td><code>only-if-cached</code></td><td>只从缓存读取；仅允许与 <code>mode: &#39;same-origin&#39;</code> 一起使用</td></tr></tbody></table><p>这些值控制当前 Fetch 与浏览器 HTTP cache 的交互，不会让服务端、CDN 或 Service Worker 自动采用相同策略。</p><h3 id="_11-2-reload-与-no-cache" tabindex="-1">11.2 <code>reload</code> 与 <code>no-cache</code> <a class="header-anchor" href="#_11-2-reload-与-no-cache" aria-label="Permalink to &quot;11.2 `reload` 与 `no-cache`&quot;">​</a></h3><p><code>reload</code> 跳过已有缓存读取并发起正常请求；<code>no-cache</code> 可以利用已有响应做条件验证。两者都可能产生网络请求，但传输量和缓存更新方式不同。</p><h3 id="_11-3-service-worker-边界" tabindex="-1">11.3 Service Worker 边界 <a class="header-anchor" href="#_11-3-service-worker-边界" aria-label="Permalink to &quot;11.3 Service Worker 边界&quot;">​</a></h3><p>页面受 Service Worker 控制时，fetch 事件可以返回 Cache API 内容。<code>Request.cache</code> 主要描述浏览器 HTTP cache 交互，不能自动绕过自定义的 Service Worker 响应逻辑。</p><h2 id="_12-devtools-验证" tabindex="-1">12. DevTools 验证 <a class="header-anchor" href="#_12-devtools-验证" aria-label="Permalink to &quot;12. DevTools 验证&quot;">​</a></h2><h3 id="_12-1-保留真实缓存条件" tabindex="-1">12.1 保留真实缓存条件 <a class="header-anchor" href="#_12-1-保留真实缓存条件" aria-label="Permalink to &quot;12.1 保留真实缓存条件&quot;">​</a></h3><p>Chrome DevTools 的 Disable cache 通常只在 DevTools 打开时生效，会人为改变行为。验证生产策略时应关闭它，再进行普通导航、刷新和重新打开标签页等多种测试。</p><h3 id="_12-2-检查字段" tabindex="-1">12.2 检查字段 <a class="header-anchor" href="#_12-2-检查字段" aria-label="Permalink to &quot;12.2 检查字段&quot;">​</a></h3><p>在 Network 面板确认：</p><ul><li>Request Headers 是否出现 <code>If-None-Match</code> 或 <code>If-Modified-Since</code>；</li><li>Status 是 <code>200</code>、<code>206</code> 还是 <code>304</code>；</li><li>Response Headers 的 <code>Cache-Control</code>、<code>Age</code>、<code>ETag</code>、<code>Vary</code>；</li><li>Size 是否显示 memory cache、disk cache 或 transferred；</li><li>请求是否由 Service Worker 响应；</li><li>CDN 自定义命中字段只能作为辅助证据，名称由供应商决定。</li></ul><h3 id="_12-3-可复现验证表" tabindex="-1">12.3 可复现验证表 <a class="header-anchor" href="#_12-3-可复现验证表" aria-label="Permalink to &quot;12.3 可复现验证表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>预期网络行为</th></tr></thead><tbody><tr><td>首次访问哈希 JS</td><td>200，传输完整内容</td></tr><tr><td>同 URL 再次访问</td><td>直接缓存命中，不回源</td></tr><tr><td>HTML 未修改后刷新</td><td>条件请求，304</td></tr><tr><td>HTML 发布新版本后刷新</td><td>200，新 ETag 和新资源 URL</td></tr><tr><td>请求 <code>/api/me</code></td><td>每次回源，不出现缓存复用</td></tr></tbody></table><p>不要只看“页面似乎更新了”。状态码、请求头、响应头和传输大小共同构成验证证据。</p><h2 id="_13-常见误区" tabindex="-1">13. 常见误区 <a class="header-anchor" href="#_13-常见误区" aria-label="Permalink to &quot;13. 常见误区&quot;">​</a></h2><h3 id="_13-1-no-cache-就是不缓存" tabindex="-1">13.1 “<code>no-cache</code> 就是不缓存” <a class="header-anchor" href="#_13-1-no-cache-就是不缓存" aria-label="Permalink to &quot;13.1 “`no-cache` 就是不缓存”&quot;">​</a></h3><p>错误。它允许存储，但复用前必须验证；真正禁止存储使用 <code>no-store</code>。</p><h3 id="_13-2-加了-etag-就会缓存" tabindex="-1">13.2 “加了 ETag 就会缓存” <a class="header-anchor" href="#_13-2-加了-etag-就会缓存" aria-label="Permalink to &quot;13.2 “加了 ETag 就会缓存”&quot;">​</a></h3><p>ETag 只提供验证器。响应能否存储、何时验证仍由缓存规则和 <code>Cache-Control</code> 决定。</p><h3 id="_13-3-资源过期后一定重新下载" tabindex="-1">13.3 “资源过期后一定重新下载” <a class="header-anchor" href="#_13-3-资源过期后一定重新下载" aria-label="Permalink to &quot;13.3 “资源过期后一定重新下载”&quot;">​</a></h3><p>过期表示不能直接作为新鲜响应复用。若有验证器，服务器可以返回 <code>304</code>，无需重传响应体。</p><h3 id="_13-4-cdn-命中代表浏览器也命中" tabindex="-1">13.4 “CDN 命中代表浏览器也命中” <a class="header-anchor" href="#_13-4-cdn-命中代表浏览器也命中" aria-label="Permalink to &quot;13.4 “CDN 命中代表浏览器也命中”&quot;">​</a></h3><p>两者是不同缓存。浏览器回源到 CDN 时，CDN 可以命中；浏览器直接命中时，请求甚至不会到 CDN。</p><h3 id="_13-5-给所有资源一年缓存最省流量" tabindex="-1">13.5 “给所有资源一年缓存最省流量” <a class="header-anchor" href="#_13-5-给所有资源一年缓存最省流量" aria-label="Permalink to &quot;13.5 “给所有资源一年缓存最省流量”&quot;">​</a></h3><p>固定 URL 的 HTML 和 API 会因此长期陈旧。长期缓存需要内容哈希、版本化 URL 或可靠失效机制配合。</p><h2 id="_14-总结" tabindex="-1">14. 总结 <a class="header-anchor" href="#_14-总结" aria-label="Permalink to &quot;14. 总结&quot;">​</a></h2><ul><li>HTTP cache 的判断链是：能否存储 → 缓存键是否匹配 → 是否新鲜 → 能否验证或接受过期。</li><li><code>no-cache</code> 允许存储并要求验证；<code>no-store</code> 禁止本次交换被存储；<code>private</code> 限制共享缓存。</li><li><code>max-age</code>、<code>s-maxage</code>、<code>Age</code> 和 <code>Expires</code> 决定新鲜度，ETag 与 Last-Modified 支持过期后的条件验证。</li><li><code>Vary</code> 让缓存键覆盖内容协商维度，但变体越多，命中率越低。</li><li>哈希静态资源、HTML 入口、公开 API 和个性化 API 应使用不同策略，并通过 Network 面板验证真实结果。</li></ul><h2 id="_15-参考资料" tabindex="-1">15. 参考资料 <a class="header-anchor" href="#_15-参考资料" aria-label="Permalink to &quot;15. 参考资料&quot;">​</a></h2><ul><li><a href="https://www.rfc-editor.org/rfc/rfc9111" target="_blank" rel="noreferrer">RFC 9111: HTTP Caching</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc9110" target="_blank" rel="noreferrer">RFC 9110: HTTP Semantics</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Caching" target="_blank" rel="noreferrer">MDN: HTTP caching</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN: Cache-Control</a></li><li><a href="https://fetch.spec.whatwg.org/#http-network-or-cache-fetch" target="_blank" rel="noreferrer">Fetch Standard: HTTP-network-or-cache fetch</a></li></ul>',188)])])}const u=e(n,[["render",l]]);export{k as __pageData,u as default};
